import json
import os
from decimal import Decimal, InvalidOperation
from typing import Any, Dict, List, Optional

import boto3


def _to_float(value: Any) -> Optional[float]:
    if value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)
    try:
        return float(Decimal(str(value).replace(",", "").strip()))
    except (InvalidOperation, ValueError, TypeError):
        return None


def _clean_text(value: Any) -> Optional[str]:
    if value is None:
        return None
    text = str(value).strip()
    return text if text else None


def _find_summary_field(summary_fields: List[Dict[str, Any]], type_text: str) -> Optional[Dict[str, Any]]:
    target = type_text.upper()
    for field in summary_fields:
        if (field.get("Type", {}).get("Text") or "").upper() == target:
            return field
    return None


def _field_text(field: Optional[Dict[str, Any]]) -> Optional[str]:
    if not field:
        return None
    return (
        _clean_text(field.get("ValueDetection", {}).get("Text"))
        or _clean_text(field.get("LabelDetection", {}).get("Text"))
    )


def _field_number(field: Optional[Dict[str, Any]]) -> Optional[float]:
    return _to_float(_field_text(field))


def _normalize_line_item_groups(line_item_groups: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    items: List[Dict[str, Any]] = []
    for group in line_item_groups or []:
        for line_item in group.get("LineItems", []):
            columns: Dict[str, Dict[str, Any]] = {}
            for expense_field in line_item.get("LineItemExpenseFields", []):
                key = (expense_field.get("Type", {}).get("Text") or "").upper()
                columns[key] = expense_field

            item = {
                "description": _field_text(columns.get("ITEM")),
                "quantity": _field_number(columns.get("QUANTITY")),
                "unit_price": _field_number(columns.get("PRICE")),
                "product_code": _field_text(columns.get("PRODUCT_CODE")),
                "unit": _field_text(columns.get("UNIT")),
                "amount": _field_number(columns.get("EXPENSE_ROW")),
                "tax": _field_number(columns.get("TAX")),
            }

            if any(v is not None for v in item.values()):
                items.append(item)
    return items


def _normalize_expense_document(doc: Dict[str, Any]) -> Dict[str, Any]:
    summary_fields = doc.get("SummaryFields", [])

    vendor_name = _field_text(_find_summary_field(summary_fields, "VENDOR_NAME"))
    vendor_address = _field_text(_find_summary_field(summary_fields, "VENDOR_ADDRESS"))
    vendor_phone = _field_text(_find_summary_field(summary_fields, "VENDOR_PHONE"))
    vendor_url = _field_text(_find_summary_field(summary_fields, "VENDOR_URL"))

    receiver_name = _field_text(_find_summary_field(summary_fields, "RECEIVER_NAME"))
    receiver_address = _field_text(_find_summary_field(summary_fields, "RECEIVER_ADDRESS"))

    invoice_id = (
        _field_text(_find_summary_field(summary_fields, "INVOICE_RECEIPT_ID"))
        or _field_text(_find_summary_field(summary_fields, "RECEIPT_ID"))
    )
    purchase_order = _field_text(_find_summary_field(summary_fields, "PO_NUMBER"))
    invoice_date = _field_text(_find_summary_field(summary_fields, "INVOICE_RECEIPT_DATE"))
    due_date = _field_text(_find_summary_field(summary_fields, "DUE_DATE"))

    subtotal = _field_number(_find_summary_field(summary_fields, "SUBTOTAL"))
    tax = _field_number(_find_summary_field(summary_fields, "TOTAL_TAX"))
    total = _field_number(_find_summary_field(summary_fields, "TOTAL"))
    discount = _field_number(_find_summary_field(summary_fields, "DISCOUNT"))
    shipping = _field_number(_find_summary_field(summary_fields, "SHIPPING_HANDLING_CHARGE"))
    tip = _field_number(_find_summary_field(summary_fields, "TIP"))
    currency = _field_text(_find_summary_field(summary_fields, "CURRENCY"))

    normalized = {
        "document_type": "expense",
        "provider": "aws_textract",
        "source_model": "AnalyzeExpense",
        "invoice_number": invoice_id,
        "purchase_order_number": purchase_order,
        "invoice_date": invoice_date,
        "due_date": due_date,
        "currency": currency,
        "vendor": {
            "name": vendor_name,
            "address": vendor_address,
            "phone": vendor_phone,
            "website": vendor_url,
        },
        "customer": {
            "name": receiver_name,
            "address": receiver_address,
        },
        "amounts": {
            "subtotal": subtotal,
            "tax": tax,
            "discount": discount,
            "shipping": shipping,
            "tip": tip,
            "total": total,
        },
        "line_items": _normalize_line_item_groups(doc.get("LineItemGroups", [])),
        "raw": {
            "expense_index": doc.get("ExpenseIndex"),
        },
    }

    return normalized


def extract_expense_to_standard_json(
    document_bytes: bytes,
    region_name: Optional[str] = None,
) -> str:
    client = boto3.client("textract", region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION") or "us-east-1")
    response = client.analyze_expense(Document={"Bytes": document_bytes})

    documents = response.get("ExpenseDocuments", [])
    normalized = [_normalize_expense_document(doc) for doc in documents]

    result = {
        "provider": "aws_textract",
        "operation": "AnalyzeExpense",
        "documents": normalized,
    }

    return json.dumps(result, ensure_ascii=False, indent=2)
